namespace Scada.Api.Runtime;

public static partial class ContextualHelpCatalog
{
    private static ContextualHelpField IF(string locale, string key, string pl, string el, string sl, string pd, string ed, string sd, string pe, string ee, string se) =>
        new(key, Pick(locale, pl, el, sl), Pick(locale, pd, ed, sd), Pick(locale, pe, ee, se), "");

    private static IEnumerable<ContextualHelpTopic> BuildIntelligenceLearningGuides(string locale)
    {
        yield return LT(locale, "intelligence.profiles-equipment", "intelligence",
            Tx("Inteligência: perfis de sinais e equipamentos", "Intelligence: signal profiles and Equipment", "Inteligencia: perfiles de señales y equipos"),
            Tx("Reúna os TAGs de uma máquina em um perfil e diga a qual equipamento esse perfil pertence.", "Gather a machine's TAGs in a profile and specify which Equipment uses it.", "Reúna TAGs de una máquina en un perfil e indique a qué equipo pertenece."),
            [
                LS(locale, "Comece com um equipamento conhecido", "Start with familiar Equipment", "Empiece por un equipo conocido",
                    "Para uma bomba, você pode ter corrente, velocidade, vazão e pressão. Não precisa inventar um sensor de vibração se ele não existe. Crie um perfil com os sinais disponíveis e relevantes; marque como obrigatórios aqueles sem os quais a comparação pretendida não faz sentido. Uma análise futura ainda pode exigir entradas específicas que seu perfil não oferece.",
                    "For a pump you might have current, speed, flow and pressure. Do not invent a vibration sensor that is absent. Build a profile from relevant available signals and mark as required those without which the intended comparison is meaningless. A particular analysis can still require inputs your profile does not provide.",
                    "Para una bomba puede disponer de corriente, velocidad, caudal y presión. No invente un sensor de vibración ausente. Cree un perfil con señales disponibles y relevantes; marque obligatorias las necesarias para la comparación. Un análisis particular puede exigir entradas que el perfil no ofrece."),
                new ContextualHelpSection(Pick(locale, "O que preencher no perfil", "What to fill in the profile", "Qué completar en el perfil"), Pick(locale,
                    "O perfil descreve as medições; a associação identifica o equipamento que usa essas medições. Os seletores mantêm os IDs internos para você. Não digite GUIDs nem copie referências de outro projeto.",
                    "The profile describes measurements; the assignment identifies the Equipment using them. Pickers retain internal IDs for you. Do not type GUIDs or copy references from another project.",
                    "El perfil describe mediciones; la asignación identifica el equipo que las usa. Los selectores conservan los IDs internos. No introduzca GUIDs ni copie referencias de otro proyecto."), Fields:
                [
                    IF(locale, "profile.key", "Chave estável", "Stable key", "Clave estable", "Identificador legível do perfil. Use algo curto e único; o nome exibido é um campo separado.", "Readable profile identifier. Keep it short and unique; the display name is separate.", "Identificador legible. Use uno breve y único; el nombre visible es separado.", "bomba-descarga", "discharge-pump", "bomba-descarga"),
                    IF(locale, "profile.name", "Nome de exibição", "Display name", "Nombre visible", "Título compreensível para quem configura e consulta.", "A recognizable title for authors and readers.", "Título comprensible para quien configura y consulta.", "Bomba de recalque", "Discharge pump", "Bomba de impulsión"),
                    IF(locale, "signal.key", "Chave do sinal", "Signal key", "Clave de señal", "Distingue o sinal dentro do perfil; não é a referência do TAG.", "Distinguishes a signal within the profile; it is not the TAG reference.", "Distingue una señal dentro del perfil; no es la referencia TAG.", "corrente", "current", "corriente"),
                    IF(locale, "signal.tag", "Referência de TAG", "TAG reference", "Referencia TAG", "Escolha o TAG existente que contém a medição. Confira tipo, caminho e unidade apresentados.", "Choose the existing measurement TAG. Check its displayed type, path and unit.", "Elija el TAG de medición existente. Compruebe tipo, ruta y unidad mostrados.", "Bomba 01 · Corrente · A", "Pump 01 · Current · A", "Bomba 01 · Corriente · A"),
                    IF(locale, "signal.required", "Obrigatório ou opcional", "Required or optional", "Obligatorio u opcional", "Obrigatório indica que o sinal é necessário para o perfil. Opcional permite registrar que uma medição pode estar ausente; não garante que toda análise consiga funcionar sem ela.", "Required means the signal is needed for this profile. Optional allows a measurement to be absent; it does not guarantee every analysis works without it.", "Obligatorio indica que la señal es necesaria. Opcional permite ausencia, pero no garantiza que todo análisis funcione sin ella.", "Corrente obrigatória; vibração opcional", "Current required; vibration optional", "Corriente obligatoria; vibración opcional"),
                    IF(locale, "signal.role", "Papel descritivo e semântica controlada", "Descriptive role and controlled semantics", "Papel descriptivo y semántica controlada", "O texto de domínio descreve a medição; não é um papel de segurança. A semântica controlada declara a grandeza e pede qualificadores próprios. Complete-os conforme o instrumento; selecionar um papel não converte unidade nem deduz informações físicas.", "Domain text describes the measurement; it is not a security role. Controlled semantics declares the quantity and asks for relevant qualifiers. Fill them from the instrument; selecting a role does not convert units or infer physical information.", "El texto describe la medición; no es un rol de seguridad. La semántica declara la magnitud y pide calificadores propios. Complételos según el instrumento; no convierte unidades ni infiere información física.", "Corrente do motor; qualificadores conforme aquisição", "Motor current; qualifiers matching acquisition", "Corriente del motor; calificadores según adquisición"),
                    IF(locale, "assignment", "Associação de equipamento", "Equipment assignment", "Asignación de equipo", "Liga um perfil a uma identidade de Equipment existente. Um equipamento pode ter mais de um perfil; escolha a associação correta antes de analisar.", "Links a profile to an existing Equipment identity. Equipment can have several profiles; select the correct assignment before analysis.", "Vincula un perfil a un Equipment existente. Puede haber varios perfiles por equipo; elija la asignación correcta.", "Bomba 01 → Perfil bomba-descarga", "Pump 01 → discharge-pump profile", "Bomba 01 → perfil bomba-descarga")
                ]),
                LS(locale, "Salvar, habilitar e ativar são passos diferentes", "Saving, enabling and activation differ", "Guardar, habilitar y activar son pasos distintos",
                    "Selecione os Equipment/Location elegíveis, crie perfis e associações e salve a configuração no Working. Publique a revisão antes de ativar o escopo correspondente. A licença habilita o recurso, mas o uso é seletivo: ative apenas os escopos desejados. EngineeringModify e um grant explícito AssetProcessIntelligenceManage, global ou restrito ao recurso, continuam necessários. O papel developer inicial inclui esse grant, mas um administrador pode alterá-lo; o nome do papel por si só não é autorização. Salvar a configuração e ativar o escopo não inicia uma consulta automaticamente.",
                    "Select eligible Equipment/Location resources, create profiles/assignments and save configuration to Working. Publish the revision before activating its scope. Licensing enables the feature, but usage is selective: activate only desired scopes. EngineeringModify and an explicit global or resource-scoped AssetProcessIntelligenceManage grant are still required. The initial developer role includes that grant, but an administrator can change it; a role name alone does not authorize access. Saving configuration and activating the scope do not automatically start a query.",
                    "Seleccione Equipment/Location elegibles, cree perfiles/asignaciones y guarde en Working. Publique la revisión antes de activar el alcance. La licencia habilita el recurso, pero el uso es selectivo. Se requieren EngineeringModify y AssetProcessIntelligenceManage explícito, global o restringido. El developer inicial lo incluye, pero el administrador puede cambiarlo; el nombre del rol no autoriza por sí solo. Guardar configuración y activar el alcance no inicia una consulta automáticamente.")
            ], "intelligence.overview", "intelligence.operating-contexts", "intelligence.dashboard-workflow", "tags.overview", "security.users-roles-capabilities");

        yield return LT(locale, "intelligence.operating-contexts", "intelligence",
            Tx("Inteligência: contexto operacional e etapas", "Intelligence: operating context and stages", "Inteligencia: contexto operativo y etapas"),
            Tx("Descreva em que condição comparar um equipamento e como agrupá-lo no processo.", "Describe the conditions for comparing Equipment and how it belongs to the process.", "Describa condiciones para comparar un equipo y cómo se agrupa en el proceso."),
            [
                LS(locale, "Compare condições que tenham sentido", "Compare meaningful conditions", "Compare condiciones con sentido",
                    "Corrente maior pode ser esperada se velocidade ou carga aumentou. Um contexto operacional explicita condições, como bomba ligada e velocidade em uma faixa definida, para selecionar evidências comparáveis. Ele não aprende automaticamente o modo de operação nem transforma correlação em diagnóstico. Defina limites com conhecimento do equipamento.",
                    "Higher current may be expected when speed or load rises. An operating context states conditions, such as pump running and speed within a defined range, to select comparable evidence. It does not automatically learn operating mode or turn correlation into diagnosis. Choose limits using Equipment knowledge.",
                    "Mayor corriente puede ser esperable si aumenta velocidad o carga. El contexto explicita condiciones, como bomba en marcha y velocidad dentro de un intervalo, para seleccionar evidencia comparable. No aprende automáticamente el modo ni convierte correlación en diagnóstico. Defina límites con conocimiento del equipo."),
                LS(locale, "Preencha o contexto", "Fill in the context", "Complete el contexto",
                    "Escolha a associação de equipamento, uma chave estável e um rótulo que explique a condição. Adicione ao menos um predicado obrigatório e selecione TAGs do perfil associado. Um intervalo numérico inclui mínimo e máximo e usa a unidade atual do TAG. Boolean exige True/False; String e Enum exigem o valor exato, inclusive maiúsculas quando aplicável. Todos os predicados precisam corresponder no mesmo timestamp UTC de origem, sincronizado e exato; amostras apenas próximas no tempo não provam essa coincidência. A versão do perfil é controlada pelo servidor; em conflito, atualize e revise antes de salvar.",
                    "Choose the Equipment assignment, a stable key and a label explaining the condition. Add at least one required predicate and choose TAGs from that assignment's profile. A numeric interval includes both minimum and maximum and uses the current TAG unit. Boolean requires True/False; String and Enum require the exact value, including case where applicable. All predicates must match at the same exact synchronized UTC source timestamp; samples merely close in time do not prove coincidence. The server manages profile version; on conflict, refresh and review before saving.",
                    "Elija asignación, clave estable y etiqueta de condición. Añada al menos un predicado obligatorio con TAGs del perfil. El intervalo numérico incluye mínimo y máximo y usa la unidad actual. Boolean requiere True/False; String y Enum el valor exacto, incluidas mayúsculas cuando corresponda. Todos deben coincidir en el mismo timestamp UTC de origen sincronizado y exacto; muestras cercanas no lo demuestran. El servidor controla la versión; ante conflicto, actualice y revise antes de guardar."),
                LS(locale, "Organize etapas do processo", "Organize process stages", "Organice etapas del proceso",
                    "Uma etapa reúne associações já existentes, por exemplo captação, bombeamento e distribuição. Defina chave e nome, adicione associações e use Mover acima/abaixo para definir a ordem. Essa ordem organiza a representação; não programa uma sequência de acionamento. A consulta de membros continua atribuída a cada equipamento: reunir bombas numa etapa não cria um score conjunto nem sincroniza suas amostras.",
                    "A stage groups existing assignments, such as intake, pumping and distribution. Set key/name, add assignments and use Move up/down to set order. This order organizes representation; it does not program an actuation sequence. Member queries remain attributable to each Equipment: grouping pumps does not create a combined score or synchronize samples.",
                    "Una etapa reúne asignaciones existentes, como captación, bombeo y distribución. Defina clave/nombre, añada asignaciones y use Mover arriba/abajo. El orden organiza la representación; no programa secuencias de accionamiento. Las consultas siguen siendo de cada equipo: agrupar bombas no crea puntuación conjunta ni sincroniza muestras."),
                LS(locale, "Quando não há correspondência", "When there is no match", "Cuando no hay coincidencia",
                    "Confira associação, unidade, limites, valor exato e período. Depois confira se o Historian contém os TAGs e a evidência temporal exigida. Sem correspondência ou com dados insuficientes, o resultado não significa equipamento saudável, defeituoso ou eficiência zero. Preserve a razão apresentada antes de ampliar limites apenas para obter um número.",
                    "Check assignment, unit, limits, exact value and period. Then check Historian TAG coverage and required temporal evidence. No match or insufficient data does not mean healthy Equipment, faulty Equipment or zero efficiency. Understand the reported reason before widening limits merely to obtain a number.",
                    "Compruebe asignación, unidad, límites, valor exacto y período. Después cobertura Historian y evidencia temporal. Sin coincidencia o con datos insuficientes no significa equipo sano, averiado ni eficiencia cero. Entienda la causa antes de ampliar límites solo para obtener un número.")
            ], "intelligence.profiles-equipment", "intelligence.dashboard-workflow", "historian.overview", "tags.timestamps");

        yield return LT(locale, "intelligence.dashboard-workflow", "intelligence",
            Tx("Inteligência: gerar uma tela e consultar no Runtime", "Intelligence: generate a screen and query in Runtime", "Inteligencia: generar pantalla y consultar en Runtime"),
            Tx("Transforme a configuração de perfis em telas comuns que você pode editar e integrar à navegação.", "Turn profile configuration into ordinary editable screens and integrate them into navigation.", "Transforme perfiles en pantallas comunes editables e intégrelas en la navegación."),
            [
                LS(locale, "Escolha o que a tela vai responder", "Choose the question the screen will answer", "Elija qué responderá la pantalla",
                    "Uma visão de valores/tendências ajuda a acompanhar sinais; cobertura mostra evidência disponível; desempenho e desvio contextual usam análises específicas. Escolha um perfil ou etapa completa. As opções guiadas podem exigir uma regra de desempenho válida e seleção de sinais/intervalos de contexto. Complete cada seleção com TAGs do mesmo perfil e associação, sem juntar recursos de equipamentos diferentes por semelhança de nome.",
                    "A values/trend view helps follow signals; coverage shows available evidence; performance and contextual deviation use specific analyses. Choose a complete profile or stage. Guided options can require a valid performance rule and context signal/range selections. Complete selections with TAGs from the same profile/assignment; do not combine different Equipment merely because names look similar.",
                    "Valores/tendencias ayudan a seguir señales; cobertura muestra evidencia disponible; rendimiento y desviación usan análisis específicos. Elija perfil o etapa completos. Las opciones guiadas pueden exigir regla válida y señales/intervalos de contexto. Use TAGs del mismo perfil/asignación; no combine equipos por semejanza de nombre."),
                LS(locale, "Gere e finalize o rascunho", "Generate and finish the draft", "Genere y termine el borrador",
                    "1. Salve e revise perfis, associações e etapa. 2. Complete as seleções exigidas e escolha Criar rascunho de tela ou a ação guiada correspondente. 3. Revise a tela aberta no editor normal: título, unidade, tamanho dos objetos, legibilidade e navegação. 4. Execute Pré-visualização e Aplicar. 5. Salve, publique e ative a revisão. 6. Acrescente/valide a navegação para abrir a nova tela no Runtime. Gerar não salva nem ativa automaticamente. Essa operação usa metadados: não lê valores atuais nem consulta o Historian.",
                    "1. Save/review profiles, assignments and stage. 2. Complete required selections and choose Create screen draft or the corresponding guided action. 3. Review the normal editor's screen: title, units, object size, readability and navigation. 4. Run Preview and Apply. 5. Save, publish and activate the revision. 6. Add/check navigation to open it in Runtime. Generation does not automatically save or activate. It uses metadata: no live values or Historian are read.",
                    "1. Guarde/revise perfiles, asignaciones y etapa. 2. Complete selecciones y elija Crear borrador o la acción guiada. 3. Revise título, unidades, tamaño, lectura y navegación en el editor normal. 4. Ejecute Vista previa y Aplicar. 5. Guarde, publique y active. 6. Añada/compruebe navegación para abrir en Runtime. Generar no guarda ni activa automáticamente. Usa metadatos; no lee valores actuales ni Historian."),
                LS(locale, "Consulte e interprete com o contexto visível", "Query and interpret with context visible", "Consulte e interprete con contexto visible",
                    "No Runtime, escolha equipamento, análise e período e solicite a consulta explicitamente. Confira a identidade, revisão, unidade e avisos da resposta antes de comparar números. Nos membros de etapa, desempenho e desvio são solicitações independentes e temporárias; mudar de equipamento limpa o resultado anterior. O resultado não é diagnóstico de manutenção nem comprovação de eficiência de campo. Use os dados e limitações para orientar uma investigação do gestor.",
                    "In Runtime choose Equipment, analysis and time window, then explicitly request the query. Check identity, revision, unit and response notices before comparing numbers. Stage-member performance and deviation are independent temporary requests; changing Equipment clears the earlier result. The result is not a maintenance diagnosis or proof of field efficiency. Use evidence and limitations to guide the manager's investigation.",
                    "En Runtime elija equipo, análisis y período y solicite la consulta explícitamente. Compruebe identidad, revisión, unidad y avisos antes de comparar. Rendimiento y desviación de miembros son solicitudes independientes y temporales; cambiar equipo borra el resultado anterior. No es diagnóstico de mantenimiento ni prueba de eficiencia de campo. Use evidencia y límites para orientar investigación.")
            ], "intelligence.profiles-equipment", "intelligence.operating-contexts", "intelligence.process-stage-member-insights", "visual.first-screen", "engineering.lifecycle");
    }
}
